import re

def render(template, values):
    def repl(match):
        inner = match.group(1)
        # '{{}' case: regex may capture malformed content
        stripped = inner.strip()
        if stripped in values:
            return str(values[stripped])
        # Unknown key -> empty string
        return ""

    # Match '{{' followed by key-ish content followed by '}}'
    # '{{}' or '{{ ' etc. (malformed) won't match and are left as-is
    return re.sub(r"\{\{\s*([^{}\s](?:[^{}]*[^{}\s])?)\s*\}\}", repl, template)
